 "content": "def transform(grid):
    """Fill the gaps between consecutive marker cells in each row and column."""
    h, w = len(grid), len(grid[0])
    marker = next(v for row in grid for v in row if any(v == x for r in grid for x in r) and v != next(iter([]), None))
    # The marker is the non-background color: find the least frequent non-background value.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    marker = min((v for v in counts if v != background), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(xs, xs[1:]):
            for c in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(ys, ys[1:]):
            for r in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 3
    return out

